(function(){
  'use strict';
  const C=window.AtlasCore,Q=window.ATLAS_QUESTIONS,G=window.ATLAS_GAMES,$=s=>document.querySelector(s);
  const storage={getItem:k=>window.localStorage.getItem(k)};
  let data=C.readStore(storage),round=null,map=null,view='home',lastResult=null,toastTimer,storageWarned=false;
  data.history=data.history.filter(r=>C.validRound(r,Q));
  if(!C.validRound(data.active,Q))data.active=null;
  if(!C.validRound(data.dailyDraft,Q))data.dailyDraft=null;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const gameName=m=>m==='mixed'?'综合挑战':G[m].name;
  const kmText=km=>km<1?'< 1':Math.round(km).toLocaleString('zh-CN');
  const dateLabel=d=>`${Number(d.slice(5,7))} 月 ${Number(d.slice(8,10))} 日`;
  const total=r=>r.answers.reduce((s,a)=>s+a.score,0);
  function save(){try{window.localStorage.setItem(C.KEY,JSON.stringify(data));}catch{if(!storageWarned){toast('当前浏览器无法保存战绩，本轮仍可正常游玩');storageWarned=true;}}}
  function saveRound(){data.active=round;if(round.kind==='daily')data.dailyDraft=round;save();}
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
  function cleanup(){map?.destroy();map=null;}
  function setView(name){cleanup();view=name;document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',name==='home'&&b.dataset.action==='home'));window.scrollTo({top:0,behavior:'instant'});}
  function todayDone(){return data.history.find(r=>r.kind==='daily'&&r.date===C.dayKey());}
  function home(){setView('home');const done=todayDone(),draft=data.dailyDraft?.date===C.dayKey()?data.dailyDraft:null;const best=data.history.length?Math.max(...data.history.map(r=>r.total)):0;
    $('#app').innerHTML=`<div class="shell"><section class="hero"><div class="hero-copy"><div class="eyebrow">THE WORLD IS YOUR HOME GROUND</div><h1>你记得每个名场面。<br>也知道<em>它发生在哪？</em></h1><p class="hero-description">从波士顿的加时，到仁川的决战。<br>把你的电竞记忆，落在世界地图上。</p><div class="hero-tags"><span>5 道题</span><span>3 大电竞项目</span><span>1 张世界地图</span></div></div><div class="hero-visual"><span class="map-corner top">GLOBAL ARENA NETWORK / 001</span><div class="hero-map" id="hero-map"></div><div class="map-stamp"><small>EVERY CLUTCH HAS A PLACE</small><strong>传奇，总有坐标。</strong><span>LOCATE THE MOMENT ↗</span></div><span class="map-corner bottom">READY TO DROP YOUR PIN? +</span></div></section>
    <section class="daily-card" aria-labelledby="daily-heading"><div><div class="daily-title"><h2 id="daily-heading">每日综合挑战</h2><span class="pill">${done?'ROUND COMPLETE':'DAILY DROP'}</span></div><p>${done?'今天的主场已点亮。回顾战绩，或选择一个项目继续练习。':'CS:GO × 无畏契约 × 英雄联盟，五个坐标，一场跨越世界的对决。'}</p><div class="daily-meta"><span>${dateLabel(C.dayKey())}</span><span>满分 1,000</span><span>${done?`今日 ${done.total} 分`:'下次更新 '+countdown()}</span></div></div><button class="primary dark" data-action="daily">${done?'查看今日战绩':draft?'继续今日挑战':'开始今日挑战'} <span class="arrow">↗</span></button></section>
    <section aria-labelledby="practice-heading"><div class="section-heading"><div><h2 id="practice-heading">选择你的主场</h2><p>专注热爱的项目，随时开一局。</p></div><span>FREE PLAY / 专项练习</span></div><div class="mode-grid">${Object.entries(G).map(([id,g])=>`<button class="mode-card" style="--mode:${g.color}" data-action="practice" data-mode="${id}" aria-label="开始${g.name}专项练习"><span class="mode-top"><span class="game-symbol">${id==='cs'?'⌖':id==='val'?'V':'L'}</span><span class="subtitle">${g.subtitle}</span></span><span class="mode-art">${g.short}</span><h3>${g.name}</h3><p>${g.description}</p><span class="mode-bottom"><span>5 道题 · 随时挑战</span><span class="arrow">↗</span></span></button>`).join('')}</div></section>
    <div class="lobby-bottom"><div class="mini-stats"><span><b>${C.streak(data.history)}</b>天连续</span><span><b>${data.history.length}</b>场完成</span><span><b>${best||'—'}</b>最高分</span></div><button class="text-link" data-action="stats">查看本机战绩 ↗</button></div></div>`;
    map=new window.AtlasMap($('#hero-map'),{hero:true});document.title='CLUTCH ATLAS · 电竞地理';
  }
  function countdown(){const now=new Date(),parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(now).split(':').map(Number),remaining=86400-(parts[0]*3600+parts[1]*60+parts[2]);return `${Math.floor(remaining/3600)}h ${Math.floor(remaining%3600/60)}m`;}
  function start(mode,kind){
    if(kind==='daily'){const done=todayDone();if(done){lastResult=done;results(done);return;}if(data.dailyDraft?.date===C.dayKey()){round=data.dailyDraft;renderGame();return;}}
    const seed=kind==='daily'?C.dayKey()+':v1':`${Date.now()}:${Math.random()}`;
    const selected=C.selectQuestions(Q,mode,seed);if(selected.length!==5){toast('题目尚未准备好，请尝试其他项目');return;}
    round={id:kind==='daily'?`daily-${C.dayKey()}`:`practice-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,date:C.dayKey(),mode,kind,ids:selected.map(q=>q.id),index:0,answers:[],guess:null};saveRound();renderGame();
  }
  function current(){return Q.find(q=>q.id===round.ids[round.index]);}
  function progress(){return `<div class="round-steps" aria-label="第 ${round.index+1} 题，共 5 题">${round.ids.map((_,i)=>`<span class="${i===round.index?'current':i<round.answers.length?'done':''}"></span>`).join('')}</div>`;}
  function panel(){const q=current(),g=G[q.game],answer=round.answers[round.index];return `${progress()}<div class="question-meta"><span class="game-label" style="--mode:${g.color}">${g.name}</span><span>0${round.index+1} / 05</span></div>${answer?answerPanel(q,answer):`<div class="question-year">${q.year} / ${q.event}</div><h1>${q.prompt}</h1><p class="question-hint">在地图上选择你的答案。<br>可以先移动标记，再锁定位置。</p><div class="question-bottom"><div class="guess-info"><span>${round.guess?'已选择坐标':'等待落点'}</span><b>${round.guess?coordinates(round.guess):'点击地图选点'}</b></div><button class="primary" data-action="lock" ${round.guess?'':'disabled'}>锁定位置 <span class="arrow">⌖</span></button></div>`}`;}
  function coordinates(p){return `${Math.abs(p.lat).toFixed(1)}°${p.lat>=0?'N':'S'} ${Math.abs(p.lng).toFixed(1)}°${p.lng>=0?'E':'W'}`;}
  function answerPanel(q,a){const t=C.tier(a.score/(100*C.WEIGHTS[round.index]));return `<div class="answer-badge" style="color:${t.color}">◎ ${t.label}</div><div class="answer-place">${q.city}</div><span class="answer-country">${q.country} · ${q.year}</span><div class="answer-metrics"><div><strong>${a.score}<span style="font-size:11px;color:#718166"> / ${100*C.WEIGHTS[round.index]}</span></strong><small>本题得分</small></div><div><strong>${kmText(a.km)}<span style="font-size:11px"> km</span></strong><small>距离正确地点</small></div></div><p class="answer-story">${q.story}</p><a class="source-link" href="${q.source}" target="_blank" rel="noopener noreferrer">查看赛事官方来源 ↗</a><details class="answer-question"><summary>回看题目</summary>${q.prompt}</details><div class="question-bottom"><button class="primary" data-action="next">${round.index===4?'查看本局战绩':'下一道题'} <span class="arrow">→</span></button></div>`;}
  function renderGame(){setView('play');const q=current(),a=round.answers[round.index];$('#app').innerHTML=`<div class="play-shell"><div class="round-bar"><button class="back-link" data-action="home">← 返回大厅</button><div class="round-type">${round.kind==='daily'?'DAILY CHALLENGE':'FREE PLAY'} <b>/ ${gameName(round.mode)}</b></div><div class="score-head"><strong>${total(round)}</strong><small>/ 1,000</small></div></div><div class="play-layout"><aside class="question-panel" aria-live="polite">${panel()}</aside><section class="play-map-wrap" aria-label="选择地图位置"><div class="map-topbar"><span>WORLD MAP <span style="opacity:.4">/ REAL-WORLD LOCATIONS</span></span>${a?'<span class="map-legend"><span><i></i>你的选择</span><span><i class="correct"></i>正确地点</span></span>':'<span class="map-live">● 等待定位</span>'}</div><div class="game-map" id="game-map"></div><div class="map-guide"><span>拖动地图</span><span>滚轮 / 双指缩放</span><span>${a?'已揭晓正确地点':'点击选点，再锁定'}</span></div></section></div><div class="round-note"><span>${dateLabel(round.date)} · ${round.kind==='daily'?'每日同题 / 北京时间 00:00 更新':'自由练习 / 不影响每日成绩'}</span><span>本题最高 ${100*C.WEIGHTS[round.index]} 分 · 进度自动保存在本机</span></div></div>`;
    map=new window.AtlasMap($('#game-map'),{onPick:p=>{if(round.answers[round.index])return;round.guess={lng:+p.lng.toFixed(5),lat:+p.lat.toFixed(5)};saveRound();$('.question-panel').innerHTML=panel();map.setPoints(round.guess);}});
    if(a)map.reveal(a.guess,{...q});else if(round.guess)map.setPoints(round.guess);
    document.title=`第 ${round.index+1} 题 · ${gameName(round.mode)} | CLUTCH ATLAS`;
  }
  function lock(){if(!round||!C.validPoint(round.guess)||round.answers[round.index])return;const q=current(),km=C.distance(round.guess,q);round.answers.push({guess:{...round.guess},km,score:C.score(km,round.index)});saveRound();renderGame();$('.question-panel [data-action="next"]').focus({preventScroll:true});}
  function next(){if(!round?.answers[round.index])return;if(round.index===4){finish();return;}round.index++;round.guess=null;saveRound();renderGame();}
  function finish(){const r={...round,answers:[...round.answers],total:total(round),completedAt:new Date().toISOString()};data.history=[r,...data.history.filter(h=>h.id!==r.id)].slice(0,100);data.active=null;if(r.kind==='daily')data.dailyDraft=null;save();lastResult=r;results(r);}
  function resultRows(r){return r.ids.map((id,i)=>{const q=Q.find(q=>q.id===id),a=r.answers[i],g=G[q.game];return `<button class="result-row" data-action="review" data-index="${i}"><span class="num">0${i+1}</span><div><strong>${q.city}<span style="color:#7d8d70;font-size:10px;margin-left:8px">${q.country}</span></strong><div class="place-sub" style="color:${g.color}">${g.name} · ${q.year} · ${q.event}</div></div><span class="distance">${kmText(a.km)} km</span><span class="points">+${a.score}</span><span class="chevron">↗</span></button>`;}).join('');}
  function results(r){setView('results');lastResult=r;const t=C.tier(r.total/1000);$('#app').innerHTML=`<section class="results-shell"><div class="result-top"><div class="eyebrow">ROUND COMPLETE / ${r.kind==='daily'?'DAILY CHALLENGE':'FREE PLAY'}</div><h1>${r.total>=800?'主场感，拉满了。':r.total>=500?'电竞记忆，正在归位。':'每一次落点，都离传奇更近。'}</h1><p>${dateLabel(r.date)} · ${gameName(r.mode)} · 五个坐标已揭晓</p><div class="result-score">${r.total}<span>/ 1,000</span></div><div class="result-emojis">${r.answers.map((a,i)=>C.tier(a.score/(100*C.WEIGHTS[i])).emoji).join('')}</div><div class="result-tier" style="color:${t.color}">${t.label} / ${r.total>=800?'这局，值得发给队友。':'再认识一遍世界，再记住一个名场面。'}</div></div><div class="section-heading" style="margin-top:5px"><h2>本局复盘</h2><span>点击回看每一道题 ↗</span></div><div class="result-list">${resultRows(r)}</div><div class="result-actions"><button class="primary" data-action="share">分享给队友 <span class="arrow">↗</span></button><button class="secondary" data-action="home">返回游戏大厅</button></div><p class="results-note">${r.kind==='daily'?'今日成绩已保存。明天，同一时间再见。':'练习成绩已保存在本机，不影响今日挑战。'}</p><div class="practice-select">${Object.entries(G).map(([id,g])=>`<button style="--mode:${g.color}" data-action="practice" data-mode="${id}">再练 ${g.name} ↗</button>`).join('')}</div></section>`;document.title=`${r.total} 分 · 本局战绩 | CLUTCH ATLAS`;}
  function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-inner"><div class="modal-heading"><h2>${title}</h2><button class="modal-close" data-action="close" aria-label="关闭弹窗">×</button></div>${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
  function rules(){modal('五道题，找到你的世界主场。',`<div class="eyebrow">HOW TO PLAY</div><div class="rule-step"><span>01</span><div><h3>读懂那一刻</h3><p>从赛事与名场面的线索里，想起发生的城市。</p></div></div><div class="rule-step"><span>02</span><div><h3>在地图上落点</h3><p>拖动、缩放地图，点击选择位置。选点后仍可调整，按「锁定位置」才提交。</p></div></div><div class="rule-step"><span>03</span><div><h3>离得越近，得分越高</h3><p>35 公里内视为精准命中；超出后按距离逐渐扣分。答案按城市中心计，不要求找到场馆入口。</p></div></div><div class="rule-weight">${C.WEIGHTS.map((w,i)=>`<span><small>ROUND ${i+1}</small>${w*100}</span>`).join('')}</div><p>后面的题权重更高。一局满分 1,000，每天的综合挑战按北京时间 00:00 换题，三个专项练习随时可玩。</p><p class="modal-note">键盘也能玩：聚焦地图后用方向键移动，＋ / − 缩放，回车在地图中心选点。成绩与进度保存在当前浏览器中。</p>`);}
  function stats(){const h=data.history,best=h.length?Math.max(...h.map(r=>r.total)):0;modal('我的战绩',`<div class="eyebrow">YOUR PERSONAL RECORD</div><div class="stats-overview"><div><b>${h.length}</b><small>完成场次</small></div><div><b>${best||'—'}</b><small>最高得分</small></div><div><b>${C.streak(h)}</b><small>每日连续 / 天</small></div></div>${h.length?`<p>最近 ${Math.min(h.length,12)} 场 · 点击查看完整复盘</p>${h.slice(0,12).map(r=>`<button class="history-row" style="width:100%;text-align:left" data-action="history" data-id="${esc(r.id)}"><span>${dateLabel(r.date)}<small>${gameName(r.mode)} · ${r.kind==='daily'?'每日':'练习'}</small></span><b>${r.total} ↗</b></button>`).join('')}`:'<div class="empty-state"><p>你的第一场传奇，还没有落点。<br>完成任意一局，战绩就会出现在这里。</p><button class="primary" data-action="modal-daily">开始今日挑战 <span>↗</span></button></div>'}<p class="modal-note">仅展示当前浏览器中的真实游玩记录；最多保留最近 100 场。清除浏览器数据后，记录将被移除。</p>`);}
  function about(){modal('关于 CLUTCH ATLAS',`<div class="eyebrow">MADE FOR THE MOMENTS</div><p>献给记得每个名场面的电竞观众。以地图为入口，重新走一遍 CS:GO、无畏契约和英雄联盟的赛事足迹。</p><p>首版内置 ${Q.length} 道历史题，每题揭晓后可查阅赛事官方来源。地图使用 Natural Earth 公共领域数据，来自 <a href="https://github.com/topojson/world-atlas" target="_blank" rel="noopener noreferrer">world-atlas</a>。答案坐标按城市中心近似定位。</p><p>本版本为可离线游玩的体验版，成绩保存在本机。每日题从内置题库按北京时间生成，后续日期可能重复遇到历史题。</p><p class="modal-note">独立爱好者作品，与 Valve、Riot Games 及其赛事、战队无隶属或合作关系。所涉游戏名称归各自权利人所有。</p>`);}
  function review(index){const r=lastResult;if(!r)return;const q=Q.find(q=>q.id===r.ids[index]),a=r.answers[index];modal(`${String(index+1).padStart(2,'0')} / ${q.city}`,`<span class="game-label" style="--mode:${G[q.game].color}">${G[q.game].name} · ${q.year}</span><p style="color:#e0e8da;font-size:15px">${q.prompt}</p><div class="answer-metrics"><div><strong>${a.score} / ${100*C.WEIGHTS[index]}</strong><small>本题得分</small></div><div><strong>${kmText(a.km)} km</strong><small>距离正确城市</small></div></div><p>${q.story}</p><a class="source-link" href="${q.source}" target="_blank" rel="noopener noreferrer">查看赛事官方来源 ↗</a>`);}
  function shareText(){const r=lastResult;return `CLUTCH ATLAS · 电竞地理\n${dateLabel(r.date)} / ${gameName(r.mode)}${r.kind==='practice'?' · 练习':''}\n${r.answers.map((a,i)=>C.tier(a.score/(100*C.WEIGHTS[i])).emoji).join('')}\n${r.total} / 1,000\n五道题，一张地图。队友，你能比我更近吗？${location.protocol==='https:'?'\n'+location.origin:location.protocol==='http:'?'\n'+location.origin:''}`;}
  async function share(){const text=shareText();try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast('成绩已复制，发给队友开一局');return;}}catch{}modal('把这场战绩，发给队友。',`<textarea class="share-text" readonly aria-label="可复制的成绩文本">${esc(text)}</textarea><button class="primary" data-action="copy-fallback">选中成绩文本 <span>↗</span></button><p class="modal-note">选中后复制，即可粘贴到你和队友的群聊。</p>`);}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;switch(b.dataset.action){case'home':home();break;case'daily':start('mixed','daily');break;case'practice':start(b.dataset.mode,'practice');break;case'lock':lock();break;case'next':next();break;case'rules':rules();break;case'stats':stats();break;case'about':about();break;case'close':$('#modal').close();break;case'modal-daily':$('#modal').close();start('mixed','daily');break;case'history':{const r=data.history.find(r=>r.id===b.dataset.id);if(r){$('#modal').close();results(r);}break;}case'review':review(Number(b.dataset.index));break;case'share':share();break;case'copy-fallback':$('.share-text').focus();$('.share-text').select();break;}});
  $('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
  if(data.active) {round=data.active;renderGame();}else home();
  let renderedDay=C.dayKey();setInterval(()=>{if(view==='home'&&C.dayKey()!==renderedDay){renderedDay=C.dayKey();home();}},30000);
})();
